<script setup lang="ts">
import { t, uiLanguage, languageName, uiError } from '../lib/uiLocale'

import { computed, onMounted, onUnmounted, ref, nextTick } from 'vue'
import ChatHelp from './ChatHelp.vue'
import VoiceFileTool from './VoiceFileTool.vue'
const api = window.desktopAPI
const props = defineProps<{ accounts: any[]; selectedId?: string; initialTab?: string }>()
const emit = defineEmits(['close', 'updated'])
const tab = ref(props.initialTab || 'history'), history = ref<any[]>([]), health = ref<any>(null), update = ref<any>(null)
const busy = ref(false), message = ref(''), selected = ref<any>(null), correction = ref(''), source = ref(''), target = ref('')
const filter = ref(props.selectedId || ''), confirmNew = ref(false), diagnostics = ref(''), selectedAccounts = ref<string[]>([])
const channel = ref('stable'), quickReplies = ref<string[]>([]), replySearch = ref('')
const revisionTone = ref('')
const retention = ref(0)
async function saveRetention() { await run(async () => { await api.setContentRetention(Number(retention.value)); retention.value = (await api.contentRetention()).days }, t('本机保留期已处理。')) }
const filteredReplies = computed(() => quickReplies.value.filter(text => text.toLowerCase().includes(replySearch.value.toLowerCase())))
async function copyText(text: string) { await run(() => navigator.clipboard.writeText(text), t('已复制。')) }
const names = computed(() => Object.fromEntries(props.accounts.map(item => [item.id, item.label])))
const rows = computed(() => history.value.filter(item => !filter.value || item.request.accountId === filter.value))
const labels = computed<Record<string, string>>(() => ({ queued: t('待处理'), pending: t('待确认 / 待结算'), charged: t('已扣费'), free: t('免费处理'), cached: t('缓存恢复'), failed: t('失败，未扣费') }))
const updateLabels = computed<Record<string,string>>(() => ({available:t('待下载'),downloading:t('下载中'),interrupted:t('下载中断，可续传'),verified:t('校验通过'),opened:t('安装结果待确认'),installed:t('已安装')}))
const powerLabels = computed<Record<string,string>>(() => ({active:t('运行中'),suspend:t('休眠'),resume:t('已唤醒'),'lock-screen':t('已锁屏'),'unlock-screen':t('已解锁')}))
const connectionLabels = computed<Record<string, string>>(() => ({ paused: t('已暂停收消息'), receiving: t('接收订阅已开启'), 'page-ready': t('聊天界面可用'), closed: t('窗口未打开'), loading: t('连接中'), disconnected: t('连接中断'), offline: t('离线'), 'login-required': t('需要扫码登录') }))
const date = (value: number) => new Date(value).toLocaleString(uiLanguage.value, { hour12: false })
let timer: ReturnType<typeof setInterval> | undefined, disposed = false, refreshing = false
async function refresh() {
  if (refreshing) return
  refreshing = true
  try {
    const [records, status, updates] = await Promise.all([api.reliabilityHistory(), api.reliabilityStatus(), api.updateInfo()])
    if (!disposed) { history.value = records; health.value = status; update.value = updates; if (selected.value) {
      selected.value = records.find((item:any) => item.requestId === selected.value.requestId) || null
      if (!selected.value || selected.value.contentExpired) { source.value = ''; correction.value = ''; confirmNew.value = false }
    } }
  } finally { refreshing = false }
}
async function run(work: () => Promise<any>, success = '') {
  if (busy.value) return
  busy.value = true; message.value = ''
  try { await work(); message.value = success; await refresh() } catch (error: any) { message.value = error?.message || t('操作未完成，请重试。') }
  finally { busy.value = false }
}
function openRecord(item: any) { selected.value = item; correction.value = item.correction || item.translated || ''; source.value = item.request.text; target.value = item.request.targetLanguage; revisionTone.value = ''; confirmNew.value = false }
async function correct() { await run(async () => { await api.correctTranslation(selected.value.requestId, correction.value); selected.value = null }, t('修正已保存，不产生翻译扣费。')) }
async function translateNew() { await run(async () => { const text = await api.newTranslation(selected.value.requestId, { confirmed: true, text: source.value, targetLanguage: target.value, tone: revisionTone.value || undefined }); correction.value = text; confirmNew.value = false }, t('新翻译已完成，新请求已记录。')) }
async function setMode(id: string, mode: string) { await run(async () => { await api.setAccountMode(id, mode); emit('updated') }) }
async function bulk(mode: string) { await run(async () => { const results = await api.bulkAccountMode([...selectedAccounts.value], mode); emit('updated'); if (results.some((item: any) => !item.ok)) throw new Error(t('部分账号未完成操作，请查看各账号状态。')) }) }
async function resolveSend(id: string, action: string) { await run(() => api.resolveSendRecord(id, action), t('已保存处理结果，不会自动发送。')) }
async function retrySend(id: string) { emit('close'); await nextTick(); try { await api.resolveSendRecord(id, 'retry') } catch { /* The main process reports a recoverable error. */ } }
async function insert(text: string) { await run(async () => { if (!props.selectedId) throw new Error(t('请先选择聊天账号。')); await api.insertQuickReply(props.selectedId, text); emit('close') }) }
onMounted(async () => { await run(refresh); try { const settings = await api.getSettings(); quickReplies.value = settings.quickReplies || []; channel.value = settings.updateChannel || 'stable'; retention.value = (await api.contentRetention()).days } catch {} if (!disposed) timer = setInterval(() => { void refresh().catch(() => undefined) }, 3000) })
onUnmounted(() => { disposed = true; if (timer) clearInterval(timer) })
</script>

<template>
  <div class="modal-backdrop" @click.self="emit('close')">
    <section class="panel reliability-panel" role="dialog" aria-modal="true" :aria-label="t('翻译记录与恢复')">
      <header><div><small>HELLODOG · {{ health?.version }}</small><h2>{{ t('记录与恢复') }}</h2></div><button :aria-label="t('关闭')" @click="emit('close')">×</button></header>
      <nav class="settings-tabs"><button v-for="item in [{id:'history',name:t('翻译记录')},{id:'runtime',name:t('账号与运行')},{id:'help',name:t('快捷操作')},{id:'privacy',name:t('隐私与诊断')},{id:'updates',name:t('版本与更新')}]" :key="item.id" :aria-pressed="tab === item.id" @click="tab = item.id">{{ item.name }}</button></nav>
      <div class="reliability-scroll">
        <section v-if="tab === 'history'">
          <div class="reliability-actions"><select v-model="filter" :aria-label="t('翻译记录账号')"><option value="">{{ t('全部账号') }}</option><option v-for="account in accounts" :key="account.id" :value="account.id">{{ account.label }}</option></select><button class="secondary" :disabled="busy" @click="run(() => api.recoverTranslations(), t('已尝试核对原请求。仍待确认的翻译可展开明细查看原因；发送结果需在原对话核对。'))">{{ t('核对待确认请求') }}</button></div>
          <p class="muted">{{ t('同一任务重试沿用原编号。缓存恢复不新增扣费。不同消息即使文字相同也独立处理。') }}</p>
          <div v-if="!selected" class="receipt-list"><button v-for="item in rows" :key="item.requestId" class="receipt-row" @click="openRecord(item)"><span><b>{{ names[item.request.accountId] || t('手动翻译') }} · {{ item.request.targetLanguage }}</b><small>{{ date(item.createdAt) }}{{ t(' · 原文 ') }}{{ item.sourceCharacters }}{{ t(' 字符') }}</small><code>{{ item.requestId }}</code></span><span><b>{{ item.lastAccess === 'cache' ? t('缓存命中，本次 0 字符') : item.lastAccess === 'correction' ? t('已手动修正，本次 0 字符') : labels[item.state] }}</b><small>{{ item.state === 'charged' ? t('原请求扣费 ') + item.chargedCharacters + t(' 字符') : labels[item.state] }}</small></span></button></div>
          <p v-if="!selected && !rows.length">{{ t('暂无本机翻译记录。旧版的云端记录仍可在个人中心查看。') }}</p>
          <label v-if="selected">{{ t('单条重译语气 ') }}<select v-model="revisionTone"><option value="">{{ t('沿用原请求') }}</option><option value="natural">{{ t('自然') }}</option><option value="business">{{ t('商务') }}</option></select><small>{{ t(' 仅在确认“作为新翻译”后使用。') }}</small></label>
          <section v-if="selected" class="receipt-detail"><h3>{{ t('请求明细') }}</h3><p v-if="selected.error" role="status">{{ uiError(selected.error) }}</p><button v-if="['pending','failed'].includes(selected.state)" :disabled="busy" @click="run(() => api.retryOriginalTranslation(selected.requestId), t('翻译已处理，未重复发送聊天消息。'))">{{ t('核对并重试翻译') }}</button><code>{{ selected.requestId }}</code><p>{{ t('原文 ') }}{{ selected.sourceCharacters }}{{ t(' 字符 · ') }}{{ labels[selected.state] }}<span v-if="selected.balanceAfter !== undefined">{{ t(' · 结算时余额 ') }}{{ selected.balanceAfter }}{{ t('（历史值）') }}</span></p><p v-if="selected.queueWaitMs !== undefined">{{ t('排队 ') }}{{ selected.queueWaitMs }}{{ t(' ms · 服务处理 ') }}{{ selected.providerMs ?? t('待确认') }} ms</p><label>{{ t('原文') }}<textarea :disabled="selected.contentExpired" v-model="source" /></label><label>{{ t('目标语言') }}<input v-model="target" /></label><label>{{ t('译文，可单条修正') }}<textarea :disabled="selected.contentExpired" v-model="correction" /></label><div class="reliability-actions"><button class="primary" :disabled="busy || selected.contentExpired || !correction.trim() || !['charged','free','cached'].includes(selected.state)" @click="correct">{{ t('仅保存修正，免费') }}</button><button class="secondary" :disabled="busy || selected.contentExpired || ['queued','pending'].includes(selected.state)" @click="confirmNew = true">{{ t('作为新翻译…') }}</button><button :disabled="busy" @click="copyText(source)">{{ t('复制原文') }}</button><button :disabled="busy || !correction" @click="copyText(correction)">{{ t('复制译文') }}</button><button v-if="selected.correction" :disabled="busy" @click="run(() => api.restoreCorrection(selected.requestId), t('已恢复首次译文，不新增扣费。'))">{{ t('撤销修正') }}</button><button @click="selected = null">{{ t('收起明细') }}</button></div><div v-if="confirmNew" class="notice" role="alert"><p>{{ t('这会创建新请求，成功后按 ') }}{{ Array.from(source.trim()).length }}{{ t(' 个原文字符计费。修改原文、目标语言和主动回翻属于新翻译操作。') }}</p><button class="primary" :disabled="busy || !source.trim() || !target.trim()" @click="translateNew">{{ t('确认新翻译') }}</button><button @click="confirmNew = false">{{ t('取消') }}</button></div></section>
        </section>
        <section v-if="tab === 'runtime'">
          <p>{{ health?.online ? t('网络接口可用，平台连接以各账号状态为准。') : t('网络接口离线，草稿与请求已保留。') }}</p>
          <div class="health-metrics"><span>{{ t('启动到显示') }}<b>{{ health?.metrics.startupMs ?? t('待测') }} ms</b></span><span>{{ t('最近账号切换') }}<b>{{ health?.metrics.switchMs ?? t('待测') }} ms</b></span><span>{{ t('应用内存') }}<b>{{ health?.metrics.memoryMiB ?? t('待测') }} MiB</b></span><span>{{ t('应用 CPU') }}<b>{{ health?.metrics.cpuPercent ?? t('待测') }}%</b></span></div>
          <small>{{ t('CPU 为两次采样之间的进程合计；包含 HelloDog 子进程和最近 30 秒内报告的 Signal 官方组件，未含旧版 Signal CLI 服务。采样：') }}{{ health?.metrics.sampledAt ? date(health.metrics.sampledAt) : t('待测') }}{{ t('。系统状态：') }}{{ powerLabels[health?.metrics.powerState] || t('待确认') }}。</small>
          <p>{{ t('切换 p95：') }}{{ health?.metrics.history?.switchP95Ms ?? t('待测') }} ms（{{ health?.metrics.history?.switchSamples ?? 0 }}{{ t(' 次）；观察 ') }}{{ health?.metrics.history?.observedMinutes ?? 0 }}{{ t(' 分钟，') }}{{ health?.metrics.history?.accountCount ?? 0 }}{{ t(' 个已打开账号。内存峰值 ') }}{{ health?.metrics.history?.peakMemoryMiB?.toFixed(1) ?? t('待测') }} MiB。</p><p v-if="health?.metrics.history?.memoryGrowthPercent != null">{{ t('相同账号数下，预热后内存变化 ') }}{{ health.metrics.history.memoryGrowthPercent }}{{ t('%。这是当前运行样本，不代表已经通过 8 小时测试。') }}</p><div class="runtime-accounts"><article v-for="account in health?.accounts || []" :key="account.id"><input v-model="selectedAccounts" type="checkbox" :value="account.id" :aria-label="t('选择 ') + names[account.id]" /><div><b>{{ names[account.id] }}</b><p>{{ connectionLabels[account.state] || t('状态待核对') }} · {{ account.proxy === 'unsupported' ? t('独立代理暂不支持') : account.proxy === 'configured' ? t('独立代理已配置，连通性需检测') : t('使用系统网络') }}</p><small>{{ account.pendingTranslations }}{{ t(' 条翻译待处理 / 待确认') }}</small></div><button :disabled="busy" @click="setMode(account.id, account.state === 'paused' ? 'receiving' : 'paused')">{{ account.state === 'paused' ? t('恢复收消息') : t('暂停账号') }}</button></article></div>
          <div class="reliability-actions"><span>{{ t('已选 ') }}{{ selectedAccounts.length }}{{ t(' 个账号') }}</span><button :disabled="busy || !selectedAccounts.length" @click="bulk('paused')">{{ t('批量暂停…') }}</button><button :disabled="busy || !selectedAccounts.length" @click="bulk('receiving')">{{ t('批量恢复…') }}</button></div>
          <p>{{ t('保持收消息会保留已打开的账号连接；暂停会停止相应接收连接。锁屏仍可后台运行，电脑休眠或断网期间不能收消息。') }}</p><h3>{{ t('待处理发送') }}</h3><p v-if="!health?.pendingSends.length">{{ t('暂无待处理发送任务。') }}</p><article v-for="task in health?.pendingSends || []" :key="task.id" class="send-record"><b>{{ names[task.accountId] }}</b><p>{{ task.conversationId }} · {{ date(task.updatedAt) }}</p><blockquote>{{ task.text }}</blockquote><p>{{ ['submitting','uncertain'].includes(task.state) ? t('请在原对话中确认这条消息是否已经发出，再选择结果。') : t('草稿和已完成的译文保留在原任务中。') }}</p><div v-if="['submitting','uncertain'].includes(task.state)"><button :disabled="busy" @click="resolveSend(task.id, 'sent')">{{ t('已在原对话确认发送成功') }}</button><button :disabled="busy" @click="resolveSend(task.id, 'not-sent')">{{ t('已确认未发送，允许手动重试') }}</button></div><div v-else><button v-if="task.platform === 'whatsapp' &amp;&amp; ['draft','translating','ready'].includes(task.state)" :disabled="busy" @click="retrySend(task.id)">{{ t('回原对话重试') }}</button><button :disabled="busy" @click="resolveSend(task.id, 'cancel')">{{ t('取消待发送任务') }}</button></div><small>{{ task.id }}</small></article>
        </section>
        <section v-if="tab === 'help'"><ChatHelp /><VoiceFileTool :accounts="accounts" :selected-id="selectedId" /><h3>{{ t('快捷回复') }}</h3><p>{{ t('只填入当前账号的空输入框，确认收件人和内容后自行发送。在设置的翻译分类中编辑快捷回复。') }}</p><input v-model="replySearch" :placeholder="t('搜索快捷回复')" :aria-label="t('搜索快捷回复')" /><button v-for="(text, index) in filteredReplies" :key="index" class="quick-reply" :disabled="busy || !selectedId" @click="insert(text)">{{ text }}</button><p v-if="!quickReplies.length">{{ t('尚未添加快捷回复。') }}</p></section>
        <section v-if="tab === 'privacy'"><h3>{{ t('本机翻译内容保留期') }}</h3><p>{{ t('仅对当前 HelloDog 用户生效。清理已完成翻译的原文、译文和缓存，保留请求编号、字符数与结算结果。草稿、待处理发送、待确认翻译和平台聊天不在此范围。Signal 中随已发消息保留的原文注释仍按平台聊天规则保留。') }}</p><div class="reliability-actions"><select style="width:min(100%,280px)" v-model.number="retention" :aria-label="t('本机翻译内容保留期')"><option :value="0">{{ t('保留，手动管理') }}</option><option :value="7">{{ t('7 天') }}</option><option :value="30">{{ t('30 天') }}</option><option :value="90">{{ t('90 天') }}</option></select><button class="secondary" :disabled="busy" @click="saveRetention">{{ t('保存保留期…') }}</button></div><p>{{ t('保存前会显示当前清理范围。缩短保留期会清理旧内容，之后延长保留期也不会恢复或自动重新翻译。Signal 删除或限时消息会同步清理本机翻译副本；此设置不改变云端服务的保留规则。') }}</p><h3>{{ t('诊断信息先预览') }}</h3><p>{{ t('只包含版本、运行指标、账号数量和错误统计。不会自动上传或发送。') }}</p><button class="secondary" :disabled="busy" @click="run(async () => { diagnostics = await api.diagnosticsPreview() })">{{ t('生成预览') }}</button><pre v-if="diagnostics" class="diagnostic-preview">{{ diagnostics }}</pre><button v-if="diagnostics" class="primary" @click="run(() => api.copyDiagnostics(diagnostics), t('已复制当前预览。'))">{{ t('复制这份诊断信息') }}</button></section>
        <section v-if="tab === 'updates'"><h3>{{ t('当前版本 ') }}{{ update?.currentVersion }}</h3><button @click="run(() => api.openOfficialWebsite())">{{ t('前往官网更新') }}</button><p>{{ t('自动检查官网稳定版；发现新版本会提醒，可稍后更新。') }}</p><div class="reliability-actions"><select v-model="channel" :aria-label="t('更新渠道')"><option value="stable">{{ t('稳定版') }}</option><option value="beta">{{ t('测试版') }}</option></select><button :disabled="busy || update?.busy" @click="run(() => api.checkUpdate(channel))">{{ t('检查此渠道') }}</button></div><section v-if="update?.manifest"><h3>{{ update.manifest.version }} · {{ update.manifest.channel === 'beta' ? t('测试版') : t('稳定版') }}</h3><p>{{ update.manifest.notes }}</p><p>{{ (update.manifest.size / 1048576).toFixed(1) }}{{ t(' MiB · 下载状态 ') }}{{ updateLabels[update.phase] || t('等待检查') }}</p><progress v-if="update.busy || update.phase === 'interrupted'" :value="update.received" :max="update.manifest.size" /><code class="checksum-code">SHA-256 {{ update.manifest.sha256 }}</code><div class="reliability-actions"><button :disabled="busy || update.busy || !update.newer" @click="run(() => api.downloadUpdate())">{{ update.phase === 'interrupted' ? t('继续下载') : t('下载并校验') }}</button><button :disabled="busy || !update.newer || !['verified','opened'].includes(update.phase)" @click="run(() => api.openUpdateInstaller(), t('安装程序已打开。若安装失败，请从恢复目录还原上一版。'))">{{ t('打开已校验的安装包') }}</button></div><p v-if="update.phase === 'opened'">{{ t('安装尚待确认。原数据目录和已校验安装包均保留，安装失败可重试。') }}</p></section><p v-if="update?.recoveryDirectory">{{ t('上一版程序文件已保留。先退出 HelloDog，再从恢复目录运行 Restore-HelloDog.cmd。') }}<button :disabled="busy" @click="run(() => api.openUpdateRecovery())">{{ t('打开恢复目录') }}</button></p><p>{{ t('下载中断保留进度；校验失败的文件不能安装。打开安装包前会备份上一版程序文件；复制失败时不会启动安装。升级前请保存草稿，按安装向导退出旧版。') }}</p></section>
      </div>
      <footer><p role="status">{{ busy ? t('处理中…') : message }}</p><button class="secondary" @click="emit('close')">{{ t('关闭') }}</button></footer>
    </section>
  </div>
</template>

<style scoped>
.reliability-panel{width:min(980px,94vw);height:min(840px,92vh);display:flex;flex-direction:column;min-height:0;padding:22px;box-sizing:border-box}.reliability-panel header{display:flex;justify-content:space-between;align-items:center;flex-shrink:0}.reliability-panel h2{margin:6px 0 14px}.reliability-scroll{overflow:auto;flex:1;min-height:0;padding:12px 6px 20px}.reliability-panel footer{display:flex;gap:16px;justify-content:space-between;align-items:center;padding-top:12px;flex-shrink:0}.reliability-panel footer p{margin:0;overflow-wrap:anywhere}.reliability-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.reliability-panel p,.muted{color:#aab9c7;line-height:1.6}.receipt-list{display:grid;gap:8px;margin-top:16px}.receipt-row{display:flex;justify-content:space-between;text-align:left;gap:16px;background:#1d2832;border:1px solid #33434f;padding:14px;border-radius:10px;color:inherit;cursor:pointer;width:100%}.receipt-row span{min-width:0}.receipt-row small{display:block;margin:5px 0;color:#aab9c7}.receipt-row code,.receipt-detail code{font-size:11px;overflow-wrap:anywhere}.receipt-detail{margin-top:20px;padding:18px;border:1px solid #536677;border-radius:12px}.receipt-detail label{display:block;margin:12px 0}.receipt-detail textarea,.receipt-detail input{display:block;box-sizing:border-box;width:100%;margin-top:5px}.receipt-detail textarea{min-height:80px}.health-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.health-metrics span{padding:16px;background:#1d2832;border-radius:10px}.health-metrics b{display:block;margin-top:8px;font-size:21px}.runtime-accounts article{display:flex;align-items:center;gap:12px;border-bottom:1px solid #33434f;padding:14px 0}.runtime-accounts article div{flex:1}.runtime-accounts p{margin:4px 0}.shortcuts{display:grid;grid-template-columns:180px 1fr;gap:14px}.shortcuts dd{margin:0}.diagnostic-preview{white-space:pre-wrap;overflow-wrap:anywhere;background:#15212b;padding:16px;font-size:12px}.quick-reply{display:block;margin:8px 0;max-width:100%;white-space:normal;text-align:left}.checksum-code{display:block;overflow-wrap:anywhere;margin:12px 0}.notice{padding:14px;background:#3c3420;margin-top:12px}.settings-tabs{flex-shrink:0;flex-wrap:wrap}.reliability-panel button{min-height:34px}.reliability-panel button:disabled{opacity:.5;cursor:default}@media(max-width:750px){.health-metrics{grid-template-columns:repeat(2,1fr)}.receipt-row{flex-direction:column}.shortcuts{grid-template-columns:140px 1fr}}
</style>
